// syntax
concat()
concat(value0)
concat(value0, value1)
concat(value0, value1, ... , valueN)


const array1 = ['a', 'b', 'c'];
const array2 = ['d', 'e', 'f'];
const array3 = array1.concat(array2);
console.log(array3); // ["a", "b", "c", "d", "e", "f"]
console.log(array1.concat(array2)); // ["a", "b", "c", "d", "e", "f"]


